//! The measured size of each causal edge (causality graph stage 5, `docs/features/causality-graph.md`
//! section 16). `content/strengths.json` is GENERATED by the sign-test harness (`sim_model::sign_probe`,
//! `crates/sim-model/src/sign_tests`, `tests/mechanism_signs`), never edited by hand. This module only
//! holds the shape of the file, parsing, rendering and merging (no file I/O, no model logic).
use serde::{Deserialize, Serialize};

/// One edge: the (decision or mechanism, input, output) triple and how big the response was.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct StrengthEntry {
    pub via: String,
    pub from: String,
    pub to: String,
    /// `perturbed` (pure code) or `system` (a whole system on a real state): which harness wrote it.
    pub basis: String,
    /// `elasticity` (median arc elasticity), `slope` (no usable levels: raw output change per input
    /// change, not comparable), `switch` (the output is a yes or no) or `unmeasured`.
    pub kind: String,
    pub median: f64,
    /// First and third quartile over the same samples.
    pub low: f64,
    pub high: f64,
    /// Samples that gave a number (live and with a defined size).
    pub samples: u32,
    /// Samples where the output moved (not clamped).
    pub live: u32,
    /// All samples tried.
    pub total: u32,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct StrengthFile {
    pub note: String,
    pub entries: Vec<StrengthEntry>,
}

pub fn parse(text: &str) -> Result<StrengthFile, String> {
    serde_json::from_str(text).map_err(|e| format!("content/strengths.json: {e}"))
}

/// One entry per line, so the file diffs line by line.
pub fn render(f: &StrengthFile) -> String {
    let note = serde_json::to_string(&f.note).unwrap_or_default();
    let rows: Vec<String> = f
        .entries
        .iter()
        .map(|e| format!("    {}", serde_json::to_string(e).unwrap_or_default()))
        .collect();
    format!(
        "{{\n  \"note\": {note},\n  \"entries\": [\n{}\n  ]\n}}\n",
        rows.join(",\n")
    )
}

/// Replace every entry of `basis` by `fresh`, keep the rest, sort by (via, from, to).
pub fn merge(mut existing: StrengthFile, basis: &str, fresh: Vec<StrengthEntry>) -> StrengthFile {
    existing.entries.retain(|e| e.basis != basis);
    existing.entries.extend(fresh);
    existing
        .entries
        .sort_by(|a, b| (&a.via, &a.from, &a.to).cmp(&(&b.via, &b.from, &b.to)));
    existing
}

pub const NOTE: &str = "GENERATED by the sign-test harness; do not edit. Regenerate: UPDATE_STRENGTHS=1 cargo test -p sim-model strengths_file && UPDATE_STRENGTHS=1 cargo test -p sim-engine --test mechanism_signs system_strengths (docs/how-to.md section 31).";
